function validate([operations, args]) {
  if (!Array.isArray(operations) || !Array.isArray(args) || operations.length !== args.length) return 'operations and arguments must be lists of the same length.';
  if (operations[0] !== 'FrequencyTracker' || !Array.isArray(args[0]) || args[0].length !== 0) return 'Start with FrequencyTracker and no arguments.';
  if (operations.length - 1 > 200000) return 'At most 2 * 10^5 calls in total.';
  for (let i = 1; i < operations.length; i++) {
    if (!['add', 'deleteOne', 'hasFrequency'].includes(operations[i])) return 'Only add, deleteOne and hasFrequency can follow the constructor.';
    const call = args[i];
    if (!Array.isArray(call) || call.length !== 1 || !Number.isInteger(call[0]) || call[0] < 1 || call[0] > 100000) return `${operations[i]} takes one integer from 1 to 10^5.`;
  }
  return null;
}

