class FrequencyTracker {
  constructor() {
    this.countOf = new Map();
    this.numbersWith = new Map();
  }

  move(from, to) {
    if (from > 0) {
      this.numbersWith.set(from, this.numbersWith.get(from) - 1);
    }
    if (to > 0) {
      this.numbersWith.set(to, (this.numbersWith.get(to) ?? 0) + 1);
    }
  }

  add(number) {
    const before = this.countOf.get(number) ?? 0;
    this.countOf.set(number, before + 1);
    this.move(before, before + 1);
  }

  deleteOne(number) {
    const before = this.countOf.get(number) ?? 0;
    if (before === 0) {
      return;
    }
    this.countOf.set(number, before - 1);
    this.move(before, before - 1);
  }

  hasFrequency(frequency) {
    return (this.numbersWith.get(frequency) ?? 0) > 0;
  }
}

