class FrequencyTracker {
  // Keep every stored copy in a plain list and count on demand.
  constructor() {
    this.items = [];
  }
  add(number) {
    this.items.push(number);
  }
  deleteOne(number) {
    const at = this.items.indexOf(number);
    if (at !== -1) this.items.splice(at, 1);
  }
  hasFrequency(frequency) {
    for (const value of new Set(this.items)) {
      if (this.items.filter(x => x === value).length === frequency) return true;
    }
    return false;
  }
}

