function generate(rand, size) {
  const pick = k => Math.floor(rand() * k);
  const large = size === 'large';
  const calls = large ? 499 : 1 + pick(10);
  const poolSize = large ? 3 + pick(30) : 1 + pick(3);
  const pool = Array.from({ length: poolSize }, (_, k) => (large && rand() < 0.3 ? 1 + pick(100000) : k + 1));
  const counts = new Map();
  const operations = ['FrequencyTracker'];
  const args = [[]];
  const addShare = 0.35 + rand() * 0.3;
  for (let c = 0; c < calls; c++) {
    const roll = rand();
    const number = pool[pick(pool.length)];
    if (roll < addShare) {
      operations.push('add');
      args.push([number]);
      counts.set(number, (counts.get(number) ?? 0) + 1);
    } else if (roll < addShare + (1 - addShare) / 2) {
      operations.push('deleteOne');
      args.push([number]);
      if (counts.get(number)) counts.set(number, counts.get(number) - 1);
    } else {
      // Half the queries ask about a frequency that some value has right now (or had recently).
      const current = counts.get(number) ?? 0;
      let frequency;
      if (rand() < 0.5 && current > 0) frequency = current + (rand() < 0.3 ? 1 : 0);
      else if (large && rand() < 0.05) frequency = 100000;
      else frequency = 1 + pick(large ? 25 : 4);
      operations.push('hasFrequency');
      args.push([frequency]);
    }
  }
  return [operations, args];
}
